28	fn decode_revert_reason(err_msg: &str) -> Option<String> {
29	    let data_prefix = "data: \"0x";
30	    let start = err_msg.find(data_prefix)? + data_prefix.len();
31	    let end = err_msg[start..].find('"')? + start;
32	    let hex_data = &err_msg[start..end];
33	
34	    if hex_data.is_empty() {
35	        return Some("(empty)".to_string());
36	    }
37	
38	    if hex_data.len() < 8 {
39	        return Some(format!("0x{}", hex_data));
40	    }
41	
42	    let bytes = alloy::hex::decode(hex_data).ok()?;
43	
44	    if bytes.len() >= 4 && bytes[0..4] == [0x08, 0xc3, 0x79, 0xa0] {
45	        if bytes.len() >= 68 {
46	            let offset = u32::from_be_bytes([bytes[4 + 28], bytes[4 + 29], bytes[4 + 30], bytes[4 + 31]]) as usize;
47	            if bytes.len() >= 36 + offset {
48	                let len_start = 4 + offset;
49	                let len = u32::from_be_bytes([bytes[len_start + 28], bytes[len_start + 29], bytes[len_start + 30], bytes[len_start + 31]]) as usize;
50	                let str_start = len_start + 32;
51	                if bytes.len() >= str_start + len {
52	                    return String::from_utf8(bytes[str_start..str_start + len].to_vec()).ok();
53	                }
54	            }
55	        }
56	    }
57	
58	    if bytes.len() >= 4 && bytes[0..4] == [0x4e, 0x48, 0x7b, 0x71] {
59	        if bytes.len() >= 36 {
60	            let code = U256::from_be_slice(&bytes[4..36]);
61	            return Some(format!("Panic(0x{:02x})", code));
62	        }
63	    }
64	
65	    if bytes.len() >= 4 {
66	        let selector: [u8; 4] = bytes[0..4].try_into().unwrap();
67	        let known_errors: &[(&str, usize)] = &[
68	            ("UnknownRoot(bytes32)", 32),
69	            ("AlreadySpent()", 0),
70	            ("ProofTooLong(uint256)", 32),
71	            ("NotOutbox(address)", 32),
72	        ];
73	        for (sig, param_len) in known_errors {
74	            let expected = &alloy::primitives::keccak256(sig)[..4];
75	            if selector == expected {
76	                if *param_len == 0 {
77	                    return Some(sig.to_string());
78	                } else if bytes.len() >= 4 + param_len {
79	                    return Some(format!("{}(0x{})", sig.split('(').next().unwrap(), alloy::hex::encode(&bytes[4..4 + param_len])));
80	                }
81	            }
82	        }
83	    }
84	
85	    Some(format!("0x{}", hex_data))
86	}
