458	impl TaskStore {
459	    pub fn new(path: impl Into<PathBuf>) -> Self {
460	        Self { path: path.into() }
461	    }
462	
463	    fn label(&self) -> String {
464	        self.path.file_stem()
465	            .map(|s| s.to_string_lossy().to_uppercase().replace("-", "_"))
466	            .unwrap_or_default()
467	    }
468	
469	    pub fn load(&self) -> RouteState {
470	        match fs::read_to_string(&self.path) {
471	            Ok(contents) => serde_json::from_str(&contents).expect("Failed to parse schedule file - data corrupted"),
472	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => RouteState::default(),
473	            Err(e) => panic!("Failed to read schedule file: {}", e),
474	        }
475	    }
476	
477	    pub fn save(&self, state: &RouteState) {
478	        if let Some(parent) = self.path.parent() {
479	            fs::create_dir_all(parent).expect("Failed to create schedules directory");
480	        }
481	        let contents = serde_json::to_string_pretty(state).expect("Failed to serialize state");
482	        fs::write(&self.path, contents).expect("Failed to write state file");
483	    }
484	
485	    pub fn add_task(&self, task: Task) {
486	        info!(logger = "TaskStore", route = self.label().as_str(), task = task.kind.name(), epoch = task.epoch, execute_after = task.execute_after, "Scheduling task");
487	        let mut state = self.load();
488	        state.tasks.push(task);
489	        self.save(&state);
490	    }
491	
492	    pub fn remove_task(&self, task: &Task) {
493	        let mut state = self.load();
494	        state.tasks.retain(|t| !(t.epoch == task.epoch && t.kind.name() == task.kind.name()));
495	        self.save(&state);
496	    }
497	
498	    pub fn reschedule_task(&self, task: &Task, execute_after: u64) {
499	        info!(logger = "TaskStore", route = self.label().as_str(), task = task.kind.name(), epoch = task.epoch, execute_after, "Rescheduling task");
500	        let mut state = self.load();
501	        for t in &mut state.tasks {
502	            if t.epoch == task.epoch && t.kind.name() == task.kind.name() {
503	                t.execute_after = execute_after;
504	                break;
505	            }
506	        }
507	        self.save(&state);
508	    }
509	
510	    /// Record the nonce and fees a transaction went out with.
511	    ///
512	    /// Written before the transaction is broadcast, so the record cannot be lost by a
513	    /// crash between broadcasting and persisting. A send that is then rejected outright
514	    /// leaves a harmless stale record: the next attempt simply sends at that nonce.
515	    pub fn set_pending_tx(&self, key: &str, nonce: u64, max_fee: u128, priority_fee: u128) {
516	        info!(logger = "TaskStore", route = self.label().as_str(), key, nonce, "Recording pending tx");
517	        let mut state = self.load();
518	        state.pending_txs.insert(key.to_string(), PendingTx { nonce, max_fee, priority_fee });
519	        self.save(&state);
520	    }
521	
522	    /// Forget a pending transaction, once its outcome is known.
523	    pub fn clear_pending_tx(&self, key: &str) {
524	        let mut state = self.load();
525	        state.pending_txs.remove(key);
526	        self.save(&state);
527	    }
528	
529	    pub fn get_pending_tx(&self, key: &str) -> Option<PendingTx> {
530	        self.load().pending_txs.get(key).cloned()
531	    }
532	
533	    pub fn update_inbox_block(&self, block: u64) {
534	        let mut state = self.load();
535	        state.inbox_last_block = Some(block);
536	        self.save(&state);
537	    }
538	
539	    pub fn update_outbox_block(&self, block: u64) {
540	        let mut state = self.load();
541	        state.outbox_last_block = Some(block);
542	        self.save(&state);
543	    }
544	
545	    pub fn set_indexing_since(&self, ts: u64) {
546	        let mut state = self.load();
547	        state.indexing_since = Some(ts);
548	        self.save(&state);
549	    }
550	
551	    pub fn initialize_sync(&self, indexing_since: u64, inbox_block: u64, outbox_block: u64) {
552	        let mut state = self.load();
553	        state.indexing_since = Some(indexing_since);
554	        state.inbox_last_block = Some(inbox_block);
555	        state.outbox_last_block = Some(outbox_block);
556	        self.save(&state);
557	    }
558	
559	    pub fn set_on_sync(&self, value: bool) {
560	        let mut state = self.load();
561	        state.on_sync = value;
562	        self.save(&state);
563	    }
564	
565	    pub fn is_on_sync(&self) -> bool {
566	        self.load().on_sync
567	    }
568	
569	    pub fn invalidate_tasks(&self, epoch: u64, kinds: &[&str]) {
570	        let mut state = self.load();
571	        let before = state.tasks.len();
572	        state.tasks.retain(|t| !(t.epoch == epoch && kinds.contains(&t.kind.name())));
573	        let removed = before - state.tasks.len();
574	        if removed > 0 {
