/// The claim preimage the outbox would be storing if `challenger` were the challenger.
///
/// `honest` is fixed to `None` because a claim with a verdict recorded can no longer be
/// challenged; [`execute`] drops out before this is reached when our record says
/// otherwise.
fn claim_preimage(stored: &ClaimData, challenger: Address) -> Claim {
    Claim {
        stateRoot: stored.state_root,
        claimer: stored.claimer,
        timestampClaimed: stored.timestamp_claimed,
        timestampVerification: stored.timestamp_verification,
        blocknumberVerification: stored.blocknumber_verification,
        honest: Party::None,
        challenger,
    }
}

pub async fn execute(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
    task_store: &Arc<Mutex<TaskStore>>,
    current_timestamp: u64,
    wallet_address: Address,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // Guards taken, used and dropped without crossing an await - see tasks/mod.rs.
    if !claim_store.lock().unwrap().exists(epoch) {
        info!(logger = "ReconcileClaim", route = route.name, epoch, "No claim on file, nothing to reconcile");
        return Ok(());
    }
    let stored = claim_store.lock().unwrap().get(epoch);

    // Past the sync window the claim is beyond what we could reconstruct anyway, and the
    // whole claim -> verify -> withdraw cycle is long over. Same bound the indexer uses
    // to decide a claim is unrecoverable.
    let expiry = u64::from(stored.timestamp_claimed).saturating_add(route.settings.sync_lookback_secs);
    if current_timestamp >= expiry {
        info!(logger = "ReconcileClaim", route = route.name, epoch, "Claim is older than the sync window, ending reconciliation");
        return Ok(());
    }

    // A verdict has been recorded, so the claim can no longer be challenged (the outbox
    // requires `honest == None`) and there is nothing left for us to re-create. That
    // verdict came from a `Verified` event the indexer only accepted once it was more
    // than 20 minutes old, which is the durability bar the rest of the bot works to.
    if stored.honest != "None" {
        info!(logger = "ReconcileClaim", route = route.name, epoch, honest = stored.honest.as_str(), "Claim already resolved, ending reconciliation");
        return Ok(());
    }

    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());

    let latest_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
    if latest_hash == FixedBytes::<32>::ZERO {
        // Either withdrawn (the outbox deletes the hash) or the claim itself was reorged
        // out. Either way there is no claim to challenge, and we must not guess at one.
        warn!(logger = "ReconcileClaim", route = route.name, epoch, "No claim hash on the outbox, ending reconciliation");
        return Ok(());
    }

    // The verdict-bearing read. `latest` could still be reorged away - which is the exact
    // failure this task exists to catch - so the claim state has to come from a block
    // that cannot change.
    let finalized_hash = outbox
        .claimHashes(U256::from(epoch))
        .block(BlockId::finalized())
        .call()
        .await?;
    if finalized_hash == FixedBytes::<32>::ZERO {
        info!(logger = "ReconcileClaim", route = route.name, epoch, "Claim not in the finalized chain yet");
        return Err(RECONCILE_PENDING.into());
    }

    // The outbox stores only a hash, so the on-chain challenger can only be established
    // by reproducing the preimage. Three candidates are reconstructible: nobody
    // challenged, we did, or the challenger we already have on file did.
    let mut candidates = vec![Address::ZERO, wallet_address];
    if stored.challenger != Address::ZERO && !candidates.contains(&stored.challenger) {
        candidates.push(stored.challenger);
    }

    let mut matched: Option<Address> = None;
    for candidate in candidates {
        if outbox.hashClaim(claim_preimage(&stored, candidate)).call().await? == finalized_hash {
            matched = Some(candidate);
            break;
        }
    }

    let Some(challenger) = matched else {
        // Someone else's challenge, a verification we have not indexed yet, or a claim
        // that differs from our record. We cannot rebuild the preimage, so we cannot act
        // on it - wait for the indexer rather than guess.
        info!(logger = "ReconcileClaim", route = route.name, epoch, "Finalized claim hash matches no reconstructible claim, waiting for the indexer");
        return Err(RECONCILE_PENDING.into());
    };

    if challenger == Address::ZERO {
        return reconcile_unchallenged(config, route, epoch, &stored, claim_store, task_store, current_timestamp).await;
    }

    adopt_challenge(route, epoch, &stored, challenger, claim_store, task_store, current_timestamp);
    // A challenge in the finalized chain cannot be reorged away, so there is nothing
    // left to re-check.
    Ok(())
}

/// The finalized chain says this claim is unchallenged. Re-run the verdict and, if it is
/// fraudulent, put a `Challenge` task back on the queue.
async fn reconcile_unchallenged(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    stored: &ClaimData,
    claim_store: &Arc<Mutex<ClaimStore>>,
    task_store: &Arc<Mutex<TaskStore>>,
    current_timestamp: u64,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    if stored.challenger != Address::ZERO {
        // We recorded a challenge that is not in the finalized chain: the `Challenged`
        // event was reorged out. The record has to match the outbox preimage or every
        // state-changing call for this epoch reverts "Invalid claim.".
        warn!(logger = "ReconcileClaim", route = route.name, epoch, challenger = ?stored.challenger, "Recorded challenge is absent from the finalized chain, clearing it");
        claim_store.lock().unwrap().update(epoch, |c| {
            c.challenger = Address::ZERO;
        });
    }

    // The event-driven path still owns this epoch; scheduling a second Challenge here
    // would only burn gas on a revert.
    let state = task_store.lock().unwrap().load();
    if state.tasks.iter().any(|t| t.epoch == epoch && matches!(t.kind, TaskKind::ValidateClaim | TaskKind::Challenge)) {
        info!(logger = "ReconcileClaim", route = route.name, epoch, "Challenge already queued, nothing to re-create");
        return Err(RECONCILE_PENDING.into());
    }

    // Propagates the `EpochNotFinalized` sentinel untouched.
    let correct_state_root = finalized_state_root(config, route, epoch).await?;

    if stored.state_root == correct_state_root {
        // Both sides of this comparison are immutable: the epoch is finalized, so the
        // snapshot can no longer change, and the claim matches it. There is no verdict
        // left to revisit.
        info!(logger = "ReconcileClaim", route = route.name, epoch, "Claim matches the finalized snapshot, ending reconciliation");
        return Ok(());
    }

    // A challenge that landed in the last few hundred blocks is real but not finalized
    // yet, so the check above cannot see it. Re-challenging on top of it would revert.
    if was_event_emitted(&route.outbox_provider, route.outbox_address, "Challenged(uint256,address)", epoch).await {
        info!(logger = "ReconcileClaim", route = route.name, epoch, "A challenge landed recently but is not finalized yet, re-checking later");
        return Err(RECONCILE_PENDING.into());
    }

    error!(logger = "ReconcileClaim", route = route.name, epoch, claimed = ?stored.state_root, correct = ?correct_state_root, "INVALID claim unchallenged in the finalized chain - rescheduling challenge");
    task_store.lock().unwrap().add_task(Task {
        epoch,
        execute_after: current_timestamp,
        kind: TaskKind::Challenge,
    });

    // Keep watching: the replacement challenge has to reach the finalized chain too.
    Err(RECONCILE_PENDING.into())
}

/// A challenge we did not know about is in the finalized chain. Bring the claim record
/// and the task queue to where the `Challenged` handler would have left them.
fn adopt_challenge(
    route: &Route,
    epoch: u64,
    stored: &ClaimData,
    challenger: Address,
    claim_store: &Arc<Mutex<ClaimStore>>,
    task_store: &Arc<Mutex<TaskStore>>,
    current_timestamp: u64,
) {
    if stored.challenger == challenger {
        info!(logger = "ReconcileClaim", route = route.name, epoch, "Challenge confirmed in the finalized chain, ending reconciliation");
        return;
    }

    warn!(logger = "ReconcileClaim", route = route.name, epoch, challenger = ?challenger, "Challenge is in the finalized chain but missing from our records - repairing");
    claim_store.lock().unwrap().update(epoch, |c| {
        c.challenger = challenger;
    });

    // Same invalidation the indexer applies on `Challenged` (see DESIGN_AND_RATIONALE.md).
    task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "Challenge", "StartVerification", "VerifySnapshot"]);

    let already_queued = task_store
        .lock()
        .unwrap()
        .load()
        .tasks
        .iter()
        .any(|t| t.epoch == epoch && matches!(t.kind, TaskKind::SendSnapshot));
    if already_queued {
        return;
    }

    task_store.lock().unwrap().add_task(Task {
        epoch,
        execute_after: current_timestamp,
        kind: TaskKind::SendSnapshot,
    });
}

