336	    #[test]
337	    fn any_true_lower_bound_returns_the_unseeded_answer() {
338	        // The whole safety argument for seeding: for every `lo` at or below the true
339	        // answer, the seeded search returns exactly what an unseeded search returns.
340	        for chain in [l1_chain(), l2_chain()] {
341	            for target_ts in 995..1_020 {
342	                let unseeded = model_search(&chain, target_ts, 0);
343	                for lo in 0..=unseeded {
344	                    assert_eq!(
345	                        model_search(&chain, target_ts, lo),
346	                        unseeded,
347	                        "target {target_ts} seeded at {lo}"
348	                    );
349	                }
350	            }
351	        }
352	    }
