385	    #[test]
386	    fn cached_seed_matches_the_unseeded_answer_on_strict_timestamps() {
387	        // Targets arrive non-decreasing (epoch ends), each re-checked a few times (the
388	        // dispatcher retries the same epoch every 30 minutes).
389	        let chain = l1_chain();
390	        let cache = AnswerCache::new();
391	        for target_ts in [1_050u64, 1_050, 1_200, 1_200, 1_400, 1_700, 1_700] {
392	            let unseeded = model_search(&chain, target_ts, 0);
393	            let seeded = model_search(&chain, target_ts, cache.seed(target_ts));
394	            assert_eq!(seeded, unseeded, "target {target_ts}");
395	            cache.update(target_ts, seeded);
396	        }
397	    }
398	
399	    #[test]
400	    fn cached_seed_stays_inside_the_target_second_on_repeated_timestamps() {
401	        // Growing chain: `(len, target)` is "the chain has `len` blocks when the epoch
402	        // end `target` is checked". The first check happens while the head still carries
403	        // `target` itself, which is the one case where the cached answer can land above
404	        // the *first* block bearing that timestamp.
405	        let chain = l2_chain();
406	        let cache = AnswerCache::new();
407	        let mut saw_divergence = false;
408	        for (len, target_ts) in [(12usize, 1_003u64), (24, 1_003), (24, 1_005), (48, 1_005)] {
409	            let visible = &chain[..len];
410	            let unseeded = model_search(visible, target_ts, 0);
411	            let seeded = model_search(visible, target_ts, cache.seed(target_ts));
412	            // Never earlier than the unseeded answer, and always the same timestamp -
413	            // so the epoch-end block is still an at-or-after-epoch-end block, and the
414	            // batch it resolves to is equal or later, i.e. conservative.
415	            assert!(seeded >= unseeded, "target {target_ts}: {seeded} < {unseeded}");
416	            assert_eq!(
417	                visible[seeded as usize], visible[unseeded as usize],
418	                "target {target_ts}: seeded block {seeded} left the target second"
419	            );
420	            saw_divergence |= seeded != unseeded;
421	            cache.update(target_ts, seeded);
422	        }
423	        assert!(saw_divergence, "fixture no longer exercises the head-clamp case");
424	    }
