275	/// `TaskKind::ReconcileClaim` has to survive a round trip through the schedule file, and
276	/// schedule files written before it existed must still load.
277	#[test]
278	fn reconcile_task_round_trips_through_disk() {
279	    let dir = tempfile::tempdir().unwrap();
280	    let store = TaskStore::new(dir.path().join("sched.json"));
281	
282	    store.add_task(vea_validator::tasks::Task {
283	        epoch: 7,
284	        execute_after: 123,
285	        kind: TaskKind::ReconcileClaim,
286	    });
287	
288	    let state = store.load();
289	    assert_eq!(state.tasks.len(), 1);
290	    assert_eq!(state.tasks[0].kind.name(), "ReconcileClaim");
291	    assert_eq!(state.tasks[0].execute_after, 123);
292	}
