mod common;

use alloy::primitives::{Address, FixedBytes, U256};
use serial_test::serial;
use std::sync::{Arc, Mutex};
use vea_validator::{
    config::ValidatorConfig,
    contracts::{IVeaInboxArbToEth, IVeaOutboxArbToEth},
