    let claim_store = Arc::new(Mutex::new(ClaimStore::new(dir.path().join("claims.json"))));
    let wallet_address = config.wallet.default_signer().address();

    let indexer = EventIndexer::new(route.clone(), wallet_address, task_store.clone(), claim_store.clone());
    indexer.initialize().await;
    task_store.lock().unwrap().set_on_sync(true);

    let dispatcher = TaskDispatcher::new(config.clone(), route.clone(), task_store.clone(), claim_store.clone());

    Harness {
        config: config.clone(),
        indexer,
        dispatcher,
        task_store,
        claim_store,
        _dir: dir,
    }
}

impl Harness {
    fn has_task(&self, epoch: u64, name: &str) -> bool {
        self.task_store
            .lock()
            .unwrap()
            .load()
            .tasks
            .iter()
            .any(|t| t.epoch == epoch && t.kind.name() == name)
    }

    fn wallet(&self) -> Address {
        self.config.wallet.default_signer().address()
    }
}

/// Fails with a readable message if the outbox chain cannot serve `finalized`, or if it
/// still lags `block` - reconciliation reads claim state at that tag and nothing else.
async fn assert_finalized_past(provider: &impl Provider, block: u64) {
    let finalized = provider
        .get_block_by_number(alloy::eips::BlockNumberOrTag::Finalized)
        .await
        .expect("devnet does not answer eth_getBlockByNumber(finalized)")
        .expect("devnet returned null for the finalized block");
    assert!(
        finalized.header.number >= block,
        "finalized block {} is still behind block {} - mine more blocks in this test",
        finalized.header.number,
        block
    );
}

/// Claims `WRONG_ROOT` for the epoch just closed and returns it, leaving the chain 20+
/// minutes past the claim so the indexer will pick it up.
async fn make_fraudulent_claim(config: &ValidatorConfig) -> u64 {
    let route = &config.build_routes()[0];
    let inbox = IVeaInboxArbToEth::new(route.inbox_address, route.inbox_provider.clone());
    let outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
    let epoch_period: u64 = inbox.epochPeriod().call().await.unwrap().try_into().unwrap();

    send_messages(route).await;
    let epoch: u64 = inbox.epochNow().call().await.unwrap().try_into().unwrap();
    inbox.saveSnapshot().send().await.unwrap().get_receipt().await.unwrap();

    advance_past_epoch(&route.outbox_provider, epoch, epoch_period).await;

    let deposit = outbox.deposit().call().await.unwrap();
    let receipt = outbox
        .claim(U256::from(epoch), WRONG_ROOT)
        .value(deposit)
        .send()
        .await
        .unwrap()
        .get_receipt()
        .await
        .unwrap();

    advance_time(20 * 60 + 10).await;
    mine_blocks(BLOCKS_TO_FINALITY).await;
    assert_finalized_past(&route.outbox_provider, receipt.block_number.unwrap()).await;
    epoch
}

async fn challenged_logs(route_outbox: Address, provider: &impl Provider) -> Vec<alloy::rpc::types::Log> {
    let sig = alloy::primitives::keccak256("Challenged(uint256,address)");
    let filter = alloy::rpc::types::Filter::new()
        .address(route_outbox)
        .event_signature(sig)
        .from_block(0u64);
    provider.get_logs(&filter).await.unwrap()
}

/// The bug this task exists for: the challenge transaction confirmed once, the dispatcher
/// retired the `Challenge` task, and then a reorg took the transaction back out. Nothing
/// in the event-driven path ever looks at that claim again.
#[tokio::test]
#[serial]
async fn test_reconcile_recreates_challenge_lost_to_reorg() {
    let c = ValidatorConfig::from_env().unwrap();
    restore_pristine().await;
    let epoch = make_fraudulent_claim(&c).await;
    let h = harness(&c).await;
    let route = &c.build_routes()[0];

    h.indexer.scan_once().await;
    assert!(h.has_task(epoch, "ValidateClaim"), "ValidateClaim should be scheduled");
    assert!(h.has_task(epoch, "ReconcileClaim"), "ReconcileClaim should be scheduled alongside it");

    // ValidateClaim schedules the challenge and retires itself.
    h.dispatcher.process_pending().await;
    assert!(h.has_task(epoch, "Challenge"), "Challenge should be scheduled");

    // Simulate the reorg: the challenge was broadcast, both tasks were retired, and the
    // chain kept no trace of it. The claim record still says unchallenged, and the outbox
    // still holds the original, unchallenged claim hash.
    h.task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "Challenge"]);
    assert!(!h.has_task(epoch, "Challenge"));
    assert!(h.has_task(epoch, "ReconcileClaim"), "the watchdog must survive");
    assert!(
        challenged_logs(route.outbox_address, &route.outbox_provider).await.is_empty(),
        "no challenge should be on chain at this point"
    );

    advance_time(RECONCILE_INTERVAL_SECS + 10).await;
    mine_blocks(BLOCKS_TO_FINALITY).await;

    h.dispatcher.process_pending().await;
    assert!(
        h.has_task(epoch, "Challenge"),
        "reconciliation should re-create the Challenge task for an unchallenged fraudulent claim"
    );

    h.dispatcher.process_pending().await;
    let logs = challenged_logs(route.outbox_address, &route.outbox_provider).await;
    assert!(!logs.is_empty(), "the re-created challenge did not reach the chain");
    assert_eq!(U256::from_be_bytes(logs[0].topics()[1].0).to::<u64>(), epoch);
}

/// The mirror case: our challenge did land and is finalized, but the `Challenged` event
/// was never indexed, so the claim record still reads `challenger == 0` and no
/// `SendSnapshot` was ever scheduled.
#[tokio::test]
#[serial]
async fn test_reconcile_adopts_unindexed_challenge() {
    let c = ValidatorConfig::from_env().unwrap();
    restore_pristine().await;
    let epoch = make_fraudulent_claim(&c).await;
    let h = harness(&c).await;
    let route = &c.build_routes()[0];

    h.indexer.scan_once().await;
    h.dispatcher.process_pending().await; // ValidateClaim -> Challenge
    h.dispatcher.process_pending().await; // Challenge executes

    let logs = challenged_logs(route.outbox_address, &route.outbox_provider).await;
    assert!(!logs.is_empty(), "challenge should have landed");
    let challenge_block = logs[0].block_number.unwrap();
    assert_eq!(
        h.claim_store.lock().unwrap().get(epoch).challenger,
        Address::ZERO,
        "the indexer has not scanned since, so the claim record cannot know about it"
    );
    assert!(!h.has_task(epoch, "SendSnapshot"), "no SendSnapshot without the event");

    advance_time(RECONCILE_INTERVAL_SECS + 10).await;
    mine_blocks(BLOCKS_TO_FINALITY).await;
    assert_finalized_past(&route.outbox_provider, challenge_block).await;

    h.dispatcher.process_pending().await;

    assert_eq!(
        h.claim_store.lock().unwrap().get(epoch).challenger,
        h.wallet(),
        "reconciliation should adopt the finalized challenge into the claim record"
    );
    assert!(h.has_task(epoch, "SendSnapshot"), "SendSnapshot should be scheduled once the challenge is re-detected");
    assert!(
        !h.has_task(epoch, "ReconcileClaim"),
        "a finalized challenge cannot be reorged away, so the watchdog retires"
    );
}

/// A claim that matches the finalized snapshot is never challenged, however many times
/// reconciliation runs, and the watchdog retires rather than spinning forever.
#[tokio::test]
#[serial]
async fn test_reconcile_leaves_valid_claim_alone() {
    let c = ValidatorConfig::from_env().unwrap();
    restore_pristine().await;
    let route = &c.build_routes()[0];

    let inbox = IVeaInboxArbToEth::new(route.inbox_address, route.inbox_provider.clone());
    let outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
    let epoch_period: u64 = inbox.epochPeriod().call().await.unwrap().try_into().unwrap();

    send_messages(route).await;
    let epoch: u64 = inbox.epochNow().call().await.unwrap().try_into().unwrap();
    inbox.saveSnapshot().send().await.unwrap().get_receipt().await.unwrap();
    let correct_root = inbox.snapshots(U256::from(epoch)).call().await.unwrap();

    advance_past_epoch(&route.outbox_provider, epoch, epoch_period).await;

    let deposit = outbox.deposit().call().await.unwrap();
    let receipt = outbox.claim(U256::from(epoch), correct_root).value(deposit).send().await.unwrap()
        .get_receipt().await.unwrap();

    advance_time(20 * 60 + 10).await;
    mine_blocks(BLOCKS_TO_FINALITY).await;
    assert_finalized_past(&route.outbox_provider, receipt.block_number.unwrap()).await;

    let h = harness(&c).await;
    h.indexer.scan_once().await;
    h.dispatcher.process_pending().await;

    // Drop the follow-up the valid branch scheduled, so only the watchdog is left.
    h.task_store.lock().unwrap().invalidate_tasks(epoch, &["ValidateClaim", "StartVerification"]);

    advance_time(RECONCILE_INTERVAL_SECS + 10).await;
    mine_blocks(BLOCKS_TO_FINALITY).await;
    h.dispatcher.process_pending().await;

    assert!(!h.has_task(epoch, "Challenge"), "a valid claim must never be challenged");
    assert!(!h.has_task(epoch, "ReconcileClaim"), "watchdog should retire on a settled valid claim");
    assert!(
        challenged_logs(route.outbox_address, &route.outbox_provider).await.is_empty(),
        "no challenge should have been sent"
    );
}

/// `TaskKind::ReconcileClaim` has to survive a round trip through the schedule file, and
/// schedule files written before it existed must still load.
#[test]
fn reconcile_task_round_trips_through_disk() {
    let dir = tempfile::tempdir().unwrap();
    let store = TaskStore::new(dir.path().join("sched.json"));

    store.add_task(vea_validator::tasks::Task {
        epoch: 7,
        execute_after: 123,
        kind: TaskKind::ReconcileClaim,
    });

    let state = store.load();
    assert_eq!(state.tasks.len(), 1);
    assert_eq!(state.tasks[0].kind.name(), "ReconcileClaim");
    assert_eq!(state.tasks[0].execute_after, 123);
}

